type ListTenantSpacesParams struct {
	TenantID        pgtype.UUID        `json:"tenant_id"`
	ArchivedSet     bool               `json:"archived_set"`
	Archived        bool               `json:"archived"`
	CursorSet       bool               `json:"cursor_set"`
	CursorCreatedAt pgtype.Timestamptz `json:"cursor_created_at"`
	CursorID        pgtype.UUID        `json:"cursor_id"`
	PageSize        int32              `json:"page_size"`
}

func (q *Queries) ListTenantSpaces(ctx context.Context, arg ListTenantSpacesParams) ([]Space, error) {
	rows, err := q.db.Query(ctx, listTenantSpaces,
		arg.TenantID,
		arg.ArchivedSet,
		arg.Archived,
		arg.CursorSet,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Space
	for rows.Next() {
		var i Space
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.TenantID,
			&i.Slug,
			&i.MediaPlane,
			&i.Metadata,
			&i.RecurringPolicy,
			&i.AdmissionPolicy,
			&i.DefaultEpisodeDurationSeconds,
			&i.MaximumEpisodeDurationSeconds,
			&i.LingerWindowSeconds,
			&i.CreatedByUserID,
			&i.UpdatedAt,
			&i.CreatedAt,
			&i.ArchivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

